{
  "technical_and_design_decisions": [
    "U1: Target the Java chaincode contract API (fabric-chaincode-java). A new Context object is created per transaction (safety prioritized over performance to avoid thread-safety issues) and passed as the first parameter to contract methods, mirroring the Node.js contract API; the Context wraps ChaincodeStub and exposes related APIs.",
    "U2/U3: Perform the protos/utils to protoutils move as a pure mechanical refactor in the Go codebase: create the protoutils package, relocate the utility/extension code, update all import paths and regenerate mocks, without providing a backward-compatibility shim (accepted breaking change).",
    "U4: Implement as a backport: cherry-pick the Kafka health-check changes from master onto the release-1.4 branch, resolve conflicts and adapt to the 1.4 codebase, then validate against a Kafka-based ordering service.",
    "U5: Implement an explicit read-only invoke rather than speculative per-operation ACLs: the peer simulates the proposal and, for callers holding only channel Reader permission, rejects any transaction whose read-write set contains writes; a new ACL resource governs read-only invocation.",
    "U6: Add a new peer configuration option for the endpoint advertised via Service Discovery, independent of the gossip external endpoint; the discovery service returns this endpoint in membership responses, falling back to the gossip external endpoint when unset.",
    "U7: Expose version information through the existing operations HTTP service for both peer and orderer (e.g., GET /version returning JSON with version and commit metadata), reusing the operations server infrastructure rather than adding a new service.",
    "U8: Rework the Go samples (chaincode and application samples) in fabric-samples to idiomatic Go style (gofmt/goimports, proper error handling, naming, package layout) without changing sample functionality.",
    "All work is done on the existing Hyperledger Fabric repositories (fabric, fabric-chaincode-java, fabric-samples) using the existing Gerrit/CI toolchain."
  ],
  "assumptions": [
    "A single experienced Hyperledger Fabric developer performs all work; estimates are effort (work-hours), not elapsed calendar time.",
    "Development environment, repositories, CI infrastructure and test tooling already exist and are operational.",
    "U2 and U3 are duplicates of the same requirement and are estimated once.",
    "U8 scope is limited to the existing Go chaincode and Go application samples in fabric-samples; no new samples are created.",
    "U4 backport covers only the Kafka health-check feature, not other ordering-service changes on master.",
    "U1 covers the Java contract API only; Node.js chaincode already provides this behavior.",
    "Estimates include design, implementation, unit/integration testing, and normal code-review rework, but exclude reviewer wait time, release management, deployment, and operational activities.",
    "No changes to consensus protocols or external proto definitions are required beyond what is stated."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1 - Design Java contract Context API",
      "activity_description": "Define the Context interface/class, per-transaction instantiation strategy for thread-safety, and the method-signature convention passing Context as the first parameter to contract methods.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Implement Context creation and injection",
      "activity_description": "Implement Context and its factory, wire per-transaction instantiation into the Java chaincode invocation runtime, and expose stub and related APIs through the Context.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Unit and integration tests",
      "activity_description": "Write unit tests for Context creation/usage and integration tests verifying contract methods receive a correct, transaction-scoped Context under concurrent invocations.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "U2/U3 - Create protoutils package and move code",
      "activity_description": "Create the new protoutils package and relocate the utilities and proto-object extensions from protos/utils.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A5",
      "activity_name": "U2/U3 - Update references and regenerate mocks",
      "activity_description": "Update all import paths and call sites across the fabric codebase to use protoutils and regenerate affected mocks and generated helpers.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "U2/U3 - Build and regression verification",
      "activity_description": "Run full builds, unit tests, and integration suites to confirm the refactor introduces no behavioral regressions; fix any fallout.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "U4 - Backport Kafka health checks to release-1.4",
      "activity_description": "Cherry-pick the Kafka health-check implementation from master onto the release-1.4 branch, resolve merge conflicts, and adapt code to the 1.4 codebase structure.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "U4 - Validate health checks on 1.4",
      "activity_description": "Run and adjust tests against a Kafka-based ordering service on the 1.4 branch, including negative scenarios (broker down) to verify health-check behavior.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "U5 - Design read-only invoke and ACL approach",
      "activity_description": "Design the read-only invocation flow: ACL resource definition, simulation-based detection of write operations, error semantics, and compatibility with existing Writer-permission invokes.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A10",
      "activity_name": "U5 - Implement read-only invoke enforcement",
      "activity_description": "Implement the peer-side logic that allows channel Readers to invoke read-only chaincode: simulate the proposal, reject read-write sets containing writes for Reader-only callers, and wire the new ACL resource into policy evaluation.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A11",
      "activity_name": "U5 - Unit and integration tests",
      "activity_description": "Test that Readers can execute query-only chaincode, that write attempts by Readers are rejected, and that existing Writer flows are unaffected, including multi-org scenarios.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A12",
      "activity_name": "U6 - Implement discovery external endpoint",
      "activity_description": "Add the new peer configuration option for the endpoint advertised via Service Discovery and modify the discovery service to return it in membership responses, with fallback to the gossip external endpoint.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A13",
      "activity_name": "U6 - Unit and integration tests",
      "activity_description": "Test configuration parsing, discovery responses with the explicit endpoint set and unset, and an end-to-end scenario with peers on a docker network discovered by an SDK client.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A14",
      "activity_name": "U7 - Add version endpoint to operations service",
      "activity_description": "Implement version reporting in the operations HTTP service for both peer and orderer, returning version/commit metadata as JSON.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A15",
      "activity_name": "U7 - Unit and integration tests",
      "activity_description": "Test the version endpoint for peer and orderer, including response format and behavior when the operations service is disabled.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A16",
      "activity_name": "U8 - Rewrite Go samples idiomatically",
      "activity_description": "Rework the Go chaincode and Go application samples in fabric-samples to idiomatic Go (formatting, error handling, naming, structure) and verify they still build and run against a test network.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A17",
      "activity_name": "Cross-cutting integration and system testing",
      "activity_description": "Run the combined increment (all merged changes) through the full integration/system test suites on the target branches and fix cross-feature issues.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A18",
      "activity_name": "Documentation and release notes",
      "activity_description": "Update documentation for the new Context API, protoutils package layout, read-only invoke ACL, discovery endpoint configuration, operations version endpoint, Kafka health-check backport, and revised samples; draft release notes.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 314
  }
}

